"""Hand written lexer for the micro language."""

from __future__ import annotations

import dataclasses

from .errors import LexError

KEYWORDS: frozenset[str] = frozenset(
    {"let", "print", "if", "else", "while", "true", "false", "and", "or", "not"}
)

# Longest match wins, so two character operators are tried first.
_OPERATORS: tuple[str, ...] = (
    "==",
    "!=",
    "<=",
    ">=",
    "+",
    "-",
    "*",
    "/",
    "%",
    "(",
    ")",
    "{",
    "}",
    ";",
    "=",
    "<",
    ">",
)

_ESCAPES: dict[str, str] = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}


@dataclasses.dataclass(frozen=True)
class Token:
    """A single lexical token."""

    kind: str
    text: str
    value: object
    offset: int


def _is_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def _is_ident_start(ch: str) -> bool:
    return ch == "_" or ch.isascii() and ch.isalpha()


def _is_ident_part(ch: str) -> bool:
    return _is_ident_start(ch) or _is_digit(ch)


def _scan_string(src: str, start: int) -> tuple[Token, int]:
    """Scan a double quoted string starting at the opening quote."""
    index = start + 1
    chunks: list[str] = []
    while True:
        if index >= len(src):
            raise LexError("unterminated string literal", start)
        ch = src[index]
        if ch == '"':
            value = "".join(chunks)
            return Token("STRING", value, value, start), index + 1
        if ch == "\n":
            raise LexError("newline inside string literal", index)
        if ch == "\\":
            if index + 1 >= len(src):
                raise LexError("unterminated string literal", start)
            escape = src[index + 1]
            if escape not in _ESCAPES:
                raise LexError(f"invalid escape sequence \\{escape}", index)
            chunks.append(_ESCAPES[escape])
            index += 2
            continue
        chunks.append(ch)
        index += 1


def _scan_exponent(src: str, index: int) -> int:
    """Return the index past an optional exponent part, validating its digits."""
    if index < len(src) and src[index] in "eE":
        cursor = index + 1
        if cursor < len(src) and src[cursor] in "+-":
            cursor += 1
        if cursor >= len(src) or not _is_digit(src[cursor]):
            raise LexError("malformed exponent in number literal", index)
        while cursor < len(src) and _is_digit(src[cursor]):
            cursor += 1
        return cursor
    return index


def _scan_number(src: str, start: int) -> tuple[Token, int]:
    """Scan an integer or float literal; ``1.`` and ``.5`` are errors."""
    index = start
    while index < len(src) and _is_digit(src[index]):
        index += 1
    if index < len(src) and src[index] == ".":
        if index + 1 >= len(src) or not _is_digit(src[index + 1]):
            raise LexError("float literal needs digits after the dot", index)
        index += 1
        while index < len(src) and _is_digit(src[index]):
            index += 1
        index = _scan_exponent(src, index)
        text = src[start:index]
        return Token("FLOAT", text, float(text), start), index
    text = src[start:index]
    return Token("INT", text, int(text), start), index


def _scan_word(src: str, start: int) -> tuple[Token, int]:
    index = start
    while index < len(src) and _is_ident_part(src[index]):
        index += 1
    text = src[start:index]
    kind = "KEYWORD" if text in KEYWORDS else "IDENT"
    return Token(kind, text, text, start), index


def _skip_trivia(src: str, index: int) -> int:
    """Skip whitespace and ``//`` comments, returning the next code index."""
    while index < len(src):
        ch = src[index]
        if ch.isspace():
            index += 1
        elif src.startswith("//", index):
            newline = src.find("\n", index)
            index = len(src) if newline == -1 else newline
        else:
            break
    return index


def tokenize(src: str) -> list[Token]:
    """Convert *src* into a list of tokens; no end-of-input token is emitted."""
    tokens: list[Token] = []
    index = 0
    while True:
        index = _skip_trivia(src, index)
        if index >= len(src):
            return tokens
        ch = src[index]
        if _is_digit(ch):
            token, index = _scan_number(src, index)
        elif _is_ident_start(ch):
            token, index = _scan_word(src, index)
        elif ch == '"':
            token, index = _scan_string(src, index)
        else:
            for op in _OPERATORS:
                if src.startswith(op, index):
                    token = Token("OP", op, op, index)
                    index += len(op)
                    break
            else:
                raise LexError(f"unexpected character {ch!r}", index)
        tokens.append(token)

"""Recursive descent parser producing a small dataclass based AST.

The AST shape is an implementation detail of this package: only ``parse``'s
error behaviour is specified.  Every node carries the offset of the token it
started at so that later stages can report useful positions.
"""

from __future__ import annotations

import dataclasses

from .errors import ParseError
from .lexer import Token, tokenize


@dataclasses.dataclass(frozen=True)
class Literal:
    """An INT, FLOAT, STRING or BOOL literal (also produced by folding)."""

    value: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Name:
    identifier: str
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Unary:
    op: str  # "-" or "not"
    operand: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Binary:
    op: str  # arithmetic or comparison operator
    left: object
    right: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Logical:
    op: str  # "and" or "or"
    left: object
    right: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Let:
    identifier: str
    expr: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Assign:
    identifier: str
    expr: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Print:
    expr: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class If:
    condition: object
    then_branch: object
    else_branch: object | None = None
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class While:
    condition: object
    body: object
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Block:
    statements: tuple[object, ...]
    offset: int = 0


@dataclasses.dataclass(frozen=True)
class Module:
    statements: tuple[object, ...]
    offset: int = 0


_COMPARISONS: frozenset[str] = frozenset({"==", "!=", "<", "<=", ">", ">="})


class _Parser:
    """Token cursor plus one method per grammar production."""

    def __init__(self, tokens: list[Token], end_offset: int) -> None:
        self.tokens: list[Token] = tokens
        self.pos: int = 0
        self.end_offset: int = end_offset

    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def offset(self) -> int:
        token = self.peek()
        return self.end_offset if token is None else token.offset

    def at(self, kind: str, text: str | None = None) -> bool:
        token = self.peek()
        if token is None or token.kind != kind:
            return False
        return text is None or token.text == text

    def advance(self) -> Token:
        token = self.peek()
        if token is None:
            raise ParseError("unexpected end of input", self.end_offset)
        self.pos += 1
        return token

    def expect(self, kind: str, text: str) -> Token:
        if not self.at(kind, text):
            raise ParseError(f"expected {text!r}", self.offset())
        return self.advance()

    # -- statements ---------------------------------------------------
    def parse_module(self) -> Module:
        statements: list[object] = []
        while self.peek() is not None:
            statements.append(self.statement())
        return Module(tuple(statements), 0)

    def statement(self) -> object:
        token = self.peek()
        if token is None:
            raise ParseError("unexpected end of input", self.end_offset)
        if token.kind == "KEYWORD":
            handler = {
                "let": self.let_statement,
                "print": self.print_statement,
                "if": self.if_statement,
                "while": self.while_statement,
            }.get(token.text)
            if handler is not None:
                return handler()
        if token.kind == "OP" and token.text == "{":
            return self.block()
        if token.kind == "IDENT":
            return self.assign_statement()
        raise ParseError("expected a statement", token.offset)

    def let_statement(self) -> Let:
        start = self.advance().offset
        name = self.identifier()
        self.expect("OP", "=")
        expr = self.expression()
        self.expect("OP", ";")
        return Let(name.text, expr, start)

    def assign_statement(self) -> Assign:
        name = self.advance()
        self.expect("OP", "=")
        expr = self.expression()
        self.expect("OP", ";")
        return Assign(name.text, expr, name.offset)

    def print_statement(self) -> Print:
        start = self.advance().offset
        expr = self.expression()
        self.expect("OP", ";")
        return Print(expr, start)

    def if_statement(self) -> If:
        start = self.advance().offset
        self.expect("OP", "(")
        condition = self.expression()
        self.expect("OP", ")")
        then_branch = self.block()
        else_branch: object | None = None
        if self.at("KEYWORD", "else"):
            self.advance()
            if self.at("KEYWORD", "if"):
                else_branch = self.if_statement()
            else:
                else_branch = self.block()
        return If(condition, then_branch, else_branch, start)

    def while_statement(self) -> While:
        start = self.advance().offset
        self.expect("OP", "(")
        condition = self.expression()
        self.expect("OP", ")")
        return While(condition, self.block(), start)

    def block(self) -> Block:
        start = self.expect("OP", "{").offset
        statements: list[object] = []
        while not self.at("OP", "}"):
            if self.peek() is None:
                raise ParseError("unterminated block", self.end_offset)
            statements.append(self.statement())
        self.advance()
        return Block(tuple(statements), start)

    def identifier(self) -> Token:
        if not self.at("IDENT"):
            raise ParseError("expected an identifier", self.offset())
        return self.advance()

    # -- expressions --------------------------------------------------
    def expression(self) -> object:
        return self.or_expr()

    def or_expr(self) -> object:
        node = self.and_expr()
        while self.at("KEYWORD", "or"):
            offset = self.advance().offset
            node = Logical("or", node, self.and_expr(), offset)
        return node

    def and_expr(self) -> object:
        node = self.not_expr()
        while self.at("KEYWORD", "and"):
            offset = self.advance().offset
            node = Logical("and", node, self.not_expr(), offset)
        return node

    def not_expr(self) -> object:
        if self.at("KEYWORD", "not"):
            offset = self.advance().offset
            return Unary("not", self.not_expr(), offset)
        return self.comparison()

    def comparison(self) -> object:
        node = self.additive()
        token = self.peek()
        if token is not None and token.kind == "OP" and token.text in _COMPARISONS:
            self.advance()
            right = self.additive()
            follow = self.peek()
            if follow is not None and follow.kind == "OP" and follow.text in _COMPARISONS:
                raise ParseError("comparison operators do not chain", follow.offset)
            return Binary(token.text, node, right, token.offset)
        return node

    def additive(self) -> object:
        node = self.multiplicative()
        while self.at("OP", "+") or self.at("OP", "-"):
            token = self.advance()
            node = Binary(token.text, node, self.multiplicative(), token.offset)
        return node

    def multiplicative(self) -> object:
        node = self.unary()
        while self.at("OP", "*") or self.at("OP", "/") or self.at("OP", "%"):
            token = self.advance()
            node = Binary(token.text, node, self.unary(), token.offset)
        return node

    def unary(self) -> object:
        if self.at("OP", "-"):
            offset = self.advance().offset
            return Unary("-", self.unary(), offset)
        return self.primary()

    def primary(self) -> object:
        token = self.peek()
        if token is None:
            raise ParseError("unexpected end of input", self.end_offset)
        if token.kind in ("INT", "FLOAT", "STRING"):
            self.advance()
            return Literal(token.value, token.offset)
        if token.kind == "KEYWORD" and token.text in ("true", "false"):
            self.advance()
            return Literal(token.text == "true", token.offset)
        if token.kind == "IDENT":
            self.advance()
            return Name(token.text, token.offset)
        if token.kind == "OP" and token.text == "(":
            self.advance()
            inner = self.expression()
            self.expect("OP", ")")
            return inner
        raise ParseError("expected an expression", token.offset)


def parse(src: str) -> object:
    """Parse *src* and return the AST root (a :class:`Module`)."""
    tokens = tokenize(src)
    return _Parser(tokens, len(src)).parse_module()

"""The stack virtual machine and the shared runtime value semantics.

The helpers in this module are the single source of truth for the language's
runtime rules; the optimizer reuses them so that folding can never disagree
with execution.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Callable

from .errors import StepLimitError, VMRuntimeError

if TYPE_CHECKING:  # pragma: no cover - import cycle avoidance only
    from .compiler import Instr, Program


def is_number(value: object) -> bool:
    """Return whether *value* counts as a number (``bool`` is not a number)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def render(value: object) -> str:
    """Render *value* the way ``print`` does."""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return value
    return str(value)


def type_name(value: object) -> str:
    """Return the language level type name of *value*."""
    if isinstance(value, bool):
        return "BOOL"
    if isinstance(value, int):
        return "INT"
    if isinstance(value, float):
        return "FLOAT"
    if isinstance(value, str):
        return "STRING"
    return type(value).__name__


def _require_numbers(op: str, left: object, right: object) -> None:
    if not (is_number(left) and is_number(right)):
        raise VMRuntimeError(
            f"{op} requires numbers, got {type_name(left)} and {type_name(right)}"
        )


def op_add(left: object, right: object) -> object:
    if isinstance(left, str) and isinstance(right, str):
        return left + right
    _require_numbers("+", left, right)
    return left + right  # type: ignore[operator]


def op_sub(left: object, right: object) -> object:
    _require_numbers("-", left, right)
    return left - right  # type: ignore[operator]


def op_mul(left: object, right: object) -> object:
    _require_numbers("*", left, right)
    return left * right  # type: ignore[operator]


def op_div(left: object, right: object) -> object:
    _require_numbers("/", left, right)
    if right == 0:
        raise VMRuntimeError("division by zero")
    return float(left) / float(right)  # type: ignore[arg-type]


def op_mod(left: object, right: object) -> object:
    if not (isinstance(left, int) and isinstance(right, int)):
        raise VMRuntimeError("% requires two INTs")
    if isinstance(left, bool) or isinstance(right, bool):
        raise VMRuntimeError("% requires two INTs")
    if right == 0:
        raise VMRuntimeError("modulo by zero")
    return left % right


def values_equal(left: object, right: object) -> bool:
    """Structural equality that never raises; BOOL never equals a number."""
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if is_number(left) and is_number(right):
        return left == right
    if isinstance(left, str) and isinstance(right, str):
        return left == right
    return False


def op_eq(left: object, right: object) -> object:
    return values_equal(left, right)


def op_ne(left: object, right: object) -> object:
    return not values_equal(left, right)


def _ordered(op: str, left: object, right: object) -> tuple[object, object]:
    if is_number(left) and is_number(right):
        return left, right
    if isinstance(left, str) and isinstance(right, str):
        return left, right
    raise VMRuntimeError(
        f"{op} requires two numbers or two STRINGs, "
        f"got {type_name(left)} and {type_name(right)}"
    )


def op_lt(left: object, right: object) -> object:
    a, b = _ordered("<", left, right)
    return a < b  # type: ignore[operator]


def op_le(left: object, right: object) -> object:
    a, b = _ordered("<=", left, right)
    return a <= b  # type: ignore[operator]


def op_gt(left: object, right: object) -> object:
    a, b = _ordered(">", left, right)
    return a > b  # type: ignore[operator]


def op_ge(left: object, right: object) -> object:
    a, b = _ordered(">=", left, right)
    return a >= b  # type: ignore[operator]


def op_neg(value: object) -> object:
    if not is_number(value):
        raise VMRuntimeError(f"unary - requires a number, got {type_name(value)}")
    return -value  # type: ignore[operator]


def op_not(value: object) -> object:
    if not isinstance(value, bool):
        raise VMRuntimeError(f"not requires a BOOL, got {type_name(value)}")
    return not value


BINARY_OPS: dict[str, Callable[[object, object], object]] = {
    "ADD": op_add,
    "SUB": op_sub,
    "MUL": op_mul,
    "DIV": op_div,
    "MOD": op_mod,
    "EQ": op_eq,
    "NE": op_ne,
    "LT": op_lt,
    "LE": op_le,
    "GT": op_gt,
    "GE": op_ge,
}

UNARY_OPS: dict[str, Callable[[object], object]] = {"NEG": op_neg, "NOT": op_not}

_MISSING = object()


class _Machine:
    """Mutable execution state for a single :func:`execute` call."""

    def __init__(self, program: "Program", step_limit: int) -> None:
        self.program: "Program" = program
        self.step_limit: int = step_limit
        self.stack: list[object] = []
        self.slots: list[object] = [_MISSING] * len(program.names)
        self.output: list[str] = []
        self.ip: int = 0
        self.steps: int = 0

    def pop(self) -> object:
        if not self.stack:
            raise VMRuntimeError("stack underflow")
        return self.stack.pop()

    def fetch(self) -> "Instr":
        if not 0 <= self.ip < len(self.program.instructions):
            raise VMRuntimeError(f"instruction pointer out of range: {self.ip}")
        instr = self.program.instructions[self.ip]
        self.ip += 1
        return instr

    def constant(self, index: int | None) -> object:
        if index is None or not 0 <= index < len(self.program.constants):
            raise VMRuntimeError(f"constant index out of range: {index}")
        return self.program.constants[index]

    def slot(self, index: int | None) -> int:
        if index is None or not 0 <= index < len(self.slots):
            raise VMRuntimeError(f"variable slot out of range: {index}")
        return index

    def load(self, index: int | None) -> object:
        position = self.slot(index)
        value = self.slots[position]
        if value is _MISSING:
            name = self.program.names[position]
            raise VMRuntimeError(f"variable {name!r} used before it was assigned")
        return value

    def jump_target(self, arg: int | None) -> int:
        if arg is None or not 0 <= arg <= len(self.program.instructions):
            raise VMRuntimeError(f"jump target out of range: {arg}")
        return arg

    def condition(self) -> bool:
        value = self.pop()
        if not isinstance(value, bool):
            raise VMRuntimeError(f"condition must be BOOL, got {type_name(value)}")
        return value

    def run(self) -> list[str]:
        while True:
            if self.steps >= self.step_limit:
                raise StepLimitError(f"step limit of {self.step_limit} exceeded")
            self.steps += 1
            instr = self.fetch()
            op, arg = instr.op, instr.arg
            if op == "CONST":
                self.stack.append(self.constant(arg))
            elif op == "LOAD":
                self.stack.append(self.load(arg))
            elif op == "STORE":
                self.slots[self.slot(arg)] = self.pop()
            elif op == "JUMP":
                self.ip = self.jump_target(arg)
            elif op == "JUMP_IF_FALSE":
                target = self.jump_target(arg)
                if not self.condition():
                    self.ip = target
            elif op == "PRINT":
                self.output.append(render(self.pop()))
            elif op == "POP":
                self.pop()
            elif op == "HALT":
                return self.output
            elif op in UNARY_OPS:
                self.stack.append(UNARY_OPS[op](self.pop()))
            elif op in BINARY_OPS:
                right = self.pop()
                left = self.pop()
                self.stack.append(BINARY_OPS[op](left, right))
            else:
                raise VMRuntimeError(f"unknown opcode {op!r}")


def execute(program: "Program", *, step_limit: int = 100_000) -> list[str]:
    """Execute *program* and return the lines it printed."""
    if isinstance(step_limit, bool) or not isinstance(step_limit, int):
        raise ValueError("step_limit must be a positive int")
    if step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    return _Machine(program, step_limit).run()

