"""Behaviour preserving constant folding over the AST.

Folding reuses the virtual machine's own operator implementations, so an
expression is folded only when evaluating it at run time would have produced
exactly the same value without raising.
"""

from __future__ import annotations

from typing import Callable

from . import parser as ast
from .errors import VMRuntimeError
from .vm import BINARY_OPS, UNARY_OPS

_BINARY_BY_SOURCE: dict[str, Callable[[object, object], object]] = {
    "+": BINARY_OPS["ADD"],
    "-": BINARY_OPS["SUB"],
    "*": BINARY_OPS["MUL"],
    "/": BINARY_OPS["DIV"],
    "%": BINARY_OPS["MOD"],
    "==": BINARY_OPS["EQ"],
    "!=": BINARY_OPS["NE"],
    "<": BINARY_OPS["LT"],
    "<=": BINARY_OPS["LE"],
    ">": BINARY_OPS["GT"],
    ">=": BINARY_OPS["GE"],
}

_UNARY_BY_SOURCE: dict[str, Callable[[object], object]] = {
    "-": UNARY_OPS["NEG"],
    "not": UNARY_OPS["NOT"],
}


def _fold_binary(node: ast.Binary) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    if isinstance(left, ast.Literal) and isinstance(right, ast.Literal):
        try:
            value = _BINARY_BY_SOURCE[node.op](left.value, right.value)
        except VMRuntimeError:
            return ast.Binary(node.op, left, right, node.offset)
        return ast.Literal(value, node.offset)
    return ast.Binary(node.op, left, right, node.offset)


def _fold_unary(node: ast.Unary) -> object:
    operand = fold_constants(node.operand)
    if isinstance(operand, ast.Literal):
        try:
            return ast.Literal(_UNARY_BY_SOURCE[node.op](operand.value), node.offset)
        except VMRuntimeError:
            return ast.Unary(node.op, operand, node.offset)
    return ast.Unary(node.op, operand, node.offset)


def _fold_logical(node: ast.Logical) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    left_bool = isinstance(left, ast.Literal) and isinstance(left.value, bool)
    right_bool = isinstance(right, ast.Literal) and isinstance(right.value, bool)
    if left_bool and right_bool:
        result = (
            left.value and right.value  # type: ignore[union-attr]
            if node.op == "and"
            else left.value or right.value  # type: ignore[union-attr]
        )
        return ast.Literal(bool(result), node.offset)
    if left_bool:
        # The right operand is never evaluated in these two cases, so its
        # runtime BOOL check may safely disappear along with it.
        if node.op == "and" and left.value is False:  # type: ignore[union-attr]
            return ast.Literal(False, node.offset)
        if node.op == "or" and left.value is True:  # type: ignore[union-attr]
            return ast.Literal(True, node.offset)
    return ast.Logical(node.op, left, right, node.offset)


def _fold_statement(node: object) -> object:
    if isinstance(node, ast.Let):
        return ast.Let(node.identifier, fold_constants(node.expr), node.offset)
    if isinstance(node, ast.Assign):
        return ast.Assign(node.identifier, fold_constants(node.expr), node.offset)
    if isinstance(node, ast.Print):
        return ast.Print(fold_constants(node.expr), node.offset)
    if isinstance(node, ast.If):
        else_branch = None if node.else_branch is None else fold_constants(node.else_branch)
        return ast.If(
            fold_constants(node.condition),
            fold_constants(node.then_branch),
            else_branch,
            node.offset,
        )
    if isinstance(node, ast.While):
        return ast.While(
            fold_constants(node.condition), fold_constants(node.body), node.offset
        )
    if isinstance(node, ast.Block):
        return ast.Block(tuple(fold_constants(s) for s in node.statements), node.offset)
    if isinstance(node, ast.Module):
        return ast.Module(tuple(fold_constants(s) for s in node.statements), node.offset)
    return node


def fold_constants(node: object) -> object:
    """Return *node* with every safely computable sub-expression folded."""
    if isinstance(node, ast.Binary):
        return _fold_binary(node)
    if isinstance(node, ast.Unary):
        return _fold_unary(node)
    if isinstance(node, ast.Logical):
        return _fold_logical(node)
    return _fold_statement(node)

"""Code generator turning the AST into a :class:`Program` of bytecode."""

from __future__ import annotations

import dataclasses

from . import parser as ast
from .errors import CompileError
from .opcodes import has_argument
from .optimizer import fold_constants
from .parser import parse

_BINARY_OPCODES: dict[str, str] = {
    "+": "ADD",
    "-": "SUB",
    "*": "MUL",
    "/": "DIV",
    "%": "MOD",
    "==": "EQ",
    "!=": "NE",
    "<": "LT",
    "<=": "LE",
    ">": "GT",
    ">=": "GE",
}


@dataclasses.dataclass(frozen=True)
class Instr:
    """A single bytecode instruction."""

    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    """A compiled program: constant pool, variable names and instructions."""

    constants: list
    names: list[str]
    instructions: list


def _collect_declarations(node: object, names: list[str]) -> None:
    """Collect ``let`` declarations in textual order.

    Blocks do not create scope, so a single flat list of slots is enough; the
    whole program is scanned first, which also makes a ``let`` in a branch that
    never runs declare its name.
    """
    if isinstance(node, ast.Let):
        if node.identifier in names:
            raise CompileError(f"variable {node.identifier!r} declared twice")
        names.append(node.identifier)
    elif isinstance(node, (ast.Module, ast.Block)):
        for statement in node.statements:
            _collect_declarations(statement, names)
    elif isinstance(node, ast.If):
        _collect_declarations(node.then_branch, names)
        if node.else_branch is not None:
            _collect_declarations(node.else_branch, names)
    elif isinstance(node, ast.While):
        _collect_declarations(node.body, names)


class _Compiler:
    """Accumulates constants and instructions while walking the AST."""

    def __init__(self, names: list[str]) -> None:
        self.names: list[str] = names
        self.slots: dict[str, int] = {name: i for i, name in enumerate(names)}
        self.constants: list = []
        self.constant_keys: dict[tuple[str, str], int] = {}
        self.code: list[Instr] = []

    def emit(self, op: str, arg: int | None = None) -> int:
        if has_argument(op) and arg is None:
            raise CompileError(f"opcode {op} requires an argument")
        self.code.append(Instr(op, arg if has_argument(op) else None))
        return len(self.code) - 1

    def patch(self, index: int, target: int) -> None:
        self.code[index] = Instr(self.code[index].op, target)

    def here(self) -> int:
        return len(self.code)

    def constant(self, value: object) -> int:
        # Deduplication is by type *and* value, so 1, 1.0 and true differ.
        key = (type(value).__name__, repr(value))
        if key not in self.constant_keys:
            self.constant_keys[key] = len(self.constants)
            self.constants.append(value)
        return self.constant_keys[key]

    def slot_of(self, identifier: str) -> int:
        if identifier not in self.slots:
            raise CompileError(f"variable {identifier!r} is not declared")
        return self.slots[identifier]

    # -- statements ---------------------------------------------------
    def statement(self, node: object) -> None:
        if isinstance(node, (ast.Let, ast.Assign)):
            self.expression(node.expr)
            self.emit("STORE", self.slot_of(node.identifier))
        elif isinstance(node, ast.Print):
            self.expression(node.expr)
            self.emit("PRINT")
        elif isinstance(node, ast.Block):
            for statement in node.statements:
                self.statement(statement)
        elif isinstance(node, ast.If):
            self.if_statement(node)
        elif isinstance(node, ast.While):
            self.while_statement(node)
        else:  # pragma: no cover - defensive
            raise CompileError(f"unsupported statement node {type(node).__name__}")

    def if_statement(self, node: ast.If) -> None:
        self.expression(node.condition)
        to_else = self.emit("JUMP_IF_FALSE", 0)
        self.statement(node.then_branch)
        if node.else_branch is None:
            self.patch(to_else, self.here())
            return
        to_end = self.emit("JUMP", 0)
        self.patch(to_else, self.here())
        self.statement(node.else_branch)
        self.patch(to_end, self.here())

    def while_statement(self, node: ast.While) -> None:
        start = self.here()
        self.expression(node.condition)
        to_end = self.emit("JUMP_IF_FALSE", 0)
        self.statement(node.body)
        self.emit("JUMP", start)
        self.patch(to_end, self.here())

    # -- expressions --------------------------------------------------
    def expression(self, node: object) -> None:
        if isinstance(node, ast.Literal):
            self.emit("CONST", self.constant(node.value))
        elif isinstance(node, ast.Name):
            self.emit("LOAD", self.slot_of(node.identifier))
        elif isinstance(node, ast.Unary):
            self.expression(node.operand)
            self.emit("NEG" if node.op == "-" else "NOT")
        elif isinstance(node, ast.Binary):
            self.expression(node.left)
            self.expression(node.right)
            self.emit(_BINARY_OPCODES[node.op])
        elif isinstance(node, ast.Logical):
            self.logical(node)
        else:  # pragma: no cover - defensive
            raise CompileError(f"unsupported expression node {type(node).__name__}")

    def logical(self, node: ast.Logical) -> None:
        """Compile ``and`` / ``or`` with jumps, keeping the strict BOOL checks.

        ``JUMP_IF_FALSE`` type checks whatever it pops, so both operands are
        still validated as BOOL exactly when they are evaluated.
        """
        false_jumps: list[int] = []
        end_jumps: list[int] = []
        self.expression(node.left)
        if node.op == "and":
            false_jumps.append(self.emit("JUMP_IF_FALSE", 0))
        else:
            to_right = self.emit("JUMP_IF_FALSE", 0)
            self.emit("CONST", self.constant(True))
            end_jumps.append(self.emit("JUMP", 0))
            self.patch(to_right, self.here())
        self.expression(node.right)
        false_jumps.append(self.emit("JUMP_IF_FALSE", 0))
        self.emit("CONST", self.constant(True))
        end_jumps.append(self.emit("JUMP", 0))
        for index in false_jumps:
            self.patch(index, self.here())
        self.emit("CONST", self.constant(False))
        for index in end_jumps:
            self.patch(index, self.here())


def compile_source(src: str, *, optimize: bool = False) -> Program:
    """Compile *src* into a :class:`Program`, optionally folding constants."""
    tree = parse(src)
    if optimize:
        tree = fold_constants(tree)
    if not isinstance(tree, ast.Module):  # pragma: no cover - defensive
        raise CompileError("parser did not return a module")
    names: list[str] = []
    _collect_declarations(tree, names)
    compiler = _Compiler(names)
    for statement in tree.statements:
        compiler.statement(statement)
    compiler.emit("HALT")
    return Program(compiler.constants, compiler.names, compiler.code)

"""Binary codec for compiled programs (magic ``MVM1``, version 1)."""

from __future__ import annotations

import struct
import zlib

from .compiler import Instr, Program
from .errors import SerializationError
from .opcodes import OPCODE_NUMBERS, OPCODES, has_argument

MAGIC: bytes = b"MVM1"
VERSION: int = 1
NO_ARG: int = 0xFFFFFFFF

_TAG_INT = 0x01
_TAG_FLOAT = 0x02
_TAG_STRING = 0x03
_TAG_BOOL = 0x04

_INT64_MIN = -(2**63)
_INT64_MAX = 2**63 - 1

_NUMBER_TO_OPCODE: dict[int, str] = {number: name for name, number in OPCODE_NUMBERS.items()}


def _encode_constant(value: object) -> bytes:
    if isinstance(value, bool):
        return bytes([_TAG_BOOL, 1 if value else 0])
    if isinstance(value, int):
        if not _INT64_MIN <= value <= _INT64_MAX:
            raise SerializationError(f"INT constant {value} does not fit in 64 bits")
        return bytes([_TAG_INT]) + struct.pack(">q", value)
    if isinstance(value, float):
        return bytes([_TAG_FLOAT]) + struct.pack(">d", value)
    if isinstance(value, str):
        payload = value.encode("utf-8")
        return bytes([_TAG_STRING]) + struct.pack(">I", len(payload)) + payload
    raise SerializationError(f"unsupported constant type {type(value).__name__}")


def _encode_instruction(instr: object) -> bytes:
    if not isinstance(instr, Instr):
        raise SerializationError("instructions must be Instr objects")
    if instr.op not in OPCODE_NUMBERS:
        raise SerializationError(f"unknown opcode {instr.op!r}")
    takes_arg = has_argument(instr.op)
    if takes_arg and instr.arg is None:
        raise SerializationError(f"opcode {instr.op} requires an argument")
    if not takes_arg and instr.arg is not None:
        raise SerializationError(f"opcode {instr.op} must not carry an argument")
    arg = NO_ARG if instr.arg is None else instr.arg
    if not 0 <= arg <= 0xFFFFFFFF or (takes_arg and arg == NO_ARG):
        raise SerializationError(f"argument out of range for {instr.op}: {instr.arg}")
    return bytes([OPCODE_NUMBERS[instr.op]]) + struct.pack(">I", arg)


def _u16_prefixed(text: str) -> bytes:
    payload = text.encode("utf-8")
    if len(payload) > 0xFFFF:
        raise SerializationError("name is too long to encode")
    return struct.pack(">H", len(payload)) + payload


def _check_count(count: int, what: str) -> None:
    if count > 0xFFFF:
        raise SerializationError(f"too many {what} to encode")


def dumps(program: Program) -> bytes:
    """Serialize *program* to its deterministic binary representation."""
    _check_count(len(program.names), "names")
    _check_count(len(program.constants), "constants")
    if len(program.instructions) > 0xFFFFFFFF:
        raise SerializationError("too many instructions to encode")
    body = bytearray()
    body.append(VERSION)
    body += struct.pack(">H", len(program.names))
    for name in program.names:
        body += _u16_prefixed(name)
    body += struct.pack(">H", len(program.constants))
    for constant in program.constants:
        body += _encode_constant(constant)
    body += struct.pack(">I", len(program.instructions))
    for instr in program.instructions:
        body += _encode_instruction(instr)
    checksum = zlib.crc32(bytes(body)) & 0xFFFFFFFF
    return MAGIC + bytes(body) + struct.pack(">I", checksum)


class _Reader:
    """Bounds checked cursor over the decoded body."""

    def __init__(self, data: bytes) -> None:
        self.data: bytes = data
        self.pos: int = 0

    def take(self, count: int) -> bytes:
        if count < 0 or self.pos + count > len(self.data):
            raise SerializationError("truncated program data")
        chunk = self.data[self.pos : self.pos + count]
        self.pos += count
        return chunk

    def u8(self) -> int:
        return self.take(1)[0]

    def u16(self) -> int:
        return struct.unpack(">H", self.take(2))[0]

    def u32(self) -> int:
        return struct.unpack(">I", self.take(4))[0]

    def at_end(self) -> bool:
        return self.pos == len(self.data)


def _decode_constant(reader: _Reader) -> object:
    tag = reader.u8()
    if tag == _TAG_INT:
        return struct.unpack(">q", reader.take(8))[0]
    if tag == _TAG_FLOAT:
        return struct.unpack(">d", reader.take(8))[0]
    if tag == _TAG_STRING:
        payload = reader.take(reader.u32())
        try:
            return payload.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise SerializationError("STRING constant is not valid UTF-8") from exc
    if tag == _TAG_BOOL:
        raw = reader.u8()
        if raw not in (0, 1):
            raise SerializationError(f"invalid BOOL payload {raw}")
        return raw == 1
    raise SerializationError(f"unknown constant tag {tag:#04x}")


def _decode_instruction(reader: _Reader) -> Instr:
    number = reader.u8()
    raw_arg = reader.u32()
    if number not in _NUMBER_TO_OPCODE:
        raise SerializationError(f"unknown opcode number {number}")
    op = _NUMBER_TO_OPCODE[number]
    if has_argument(op):
        if raw_arg == NO_ARG:
            raise SerializationError(f"opcode {op} is missing its argument")
        return Instr(op, raw_arg)
    if raw_arg != NO_ARG:
        raise SerializationError(f"opcode {op} must not carry an argument")
    return Instr(op, None)


def _decode_body(body: bytes) -> Program:
    reader = _Reader(body)
    names = [reader.take(reader.u16()).decode("utf-8", "strict") for _ in range(reader.u16())]
    constants = [_decode_constant(reader) for _ in range(reader.u16())]
    instructions = [_decode_instruction(reader) for _ in range(reader.u32())]
    if not reader.at_end():
        raise SerializationError("trailing bytes after the instruction table")
    return Program(constants, names, instructions)


def loads(data: bytes) -> Program:
    """Decode *data* into a :class:`Program`, validating it thoroughly."""
    if not isinstance(data, (bytes, bytearray)):
        raise SerializationError("program data must be bytes")
    data = bytes(data)
    if len(data) < len(MAGIC) + 1 + 4:
        raise SerializationError("truncated program data")
    if data[: len(MAGIC)] != MAGIC:
        raise SerializationError("bad magic")
    if data[len(MAGIC)] != VERSION:
        raise SerializationError(f"unsupported version {data[len(MAGIC)]}")
    body = data[len(MAGIC) : -4]
    expected = struct.unpack(">I", data[-4:])[0]
    if zlib.crc32(body) & 0xFFFFFFFF != expected:
        raise SerializationError("checksum mismatch")
    try:
        return _decode_body(body[1:])
    except (struct.error, UnicodeDecodeError) as exc:  # pragma: no cover - defensive
        raise SerializationError(f"malformed program data: {exc}") from exc


